{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C75"],
      "claim": "Glasdegib, a nitrile-containing aromatic drug with high transferability, had absolute oral bioavailability of 77.12% in healthy volunteers, supporting high F for the query's nitrile/aromatic motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Ampicillin, a zwitterionic carboxylic acid-containing drug, had absolute oral bioavailability of about 40% in humans, showing that the query's carboxylic acid does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Ketanserin, a piperidine/fluorophenyl drug, had absolute oral bioavailability of 55.5% in healthy subjects, supporting high F for the query's piperidine/fluorophenyl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Odanacatib, a lipophilic nitrile/fluorophenyl drug, had absolute oral bioavailability of 30% at 50 mg fasted, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Setipiprant, a carboxylic acid-containing drug, had human bioavailability of at least 50%, further supporting that the query's acid group is compatible with high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Meptazinol had low absolute oral bioavailability of about 8.7% due to extensive first-pass metabolism of its phenolic group; the query lacks a phenol, so this contradictory evidence has limited applicability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F ≥ 20%) because multiple high-transfer human absolute bioavailability records for structurally related piperidine, fluorophenyl, nitrile, and carboxylic acid drugs show F values from 23% to 84%, all above the threshold. The only low-F analogue, meptazinol, is explained by phenol-specific first-pass metabolism not present in the query.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule.",
    "No intravenous formulation data for the query to directly calculate absolute F.",
    "Potential dose- or solubility-limited absorption, as seen with odanacatib at higher doses, is not characterized for the query.",
    "No explicit data on efflux transporters or food effects for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

